mapper.select:
SELECT 
FROM file_system_part
WHERE file_system_part_file_id = #{fileId}
AND file_system_part_chunk_number = #{chunkNumber}
LIMIT 1


SELECT <include refid="Base_Column_List" />
FROM file_system_part
WHERE chunk_status = 3
AND retry_count < #{maxRetryCount}
ORDER BY update_time ASC


    LIMIT #{limit}


SELECT <include refid="Base_Column_List" />
FROM file_system_part
WHERE file_system_part_chunk_status = 1
AND TIMESTAMPDIFF(MINUTE, file_system_part_process_time, NOW()) > #{timeoutMinutes}
ORDER BY file_system_part_process_time ASC


    LIMIT #{limit}

SELECT file_system_part_file_id, COUNT(*) as total_chunks, SUM(CASE WHEN file_system_part_chunk_status = 2 THEN 1 ELSE 0 END) as completed_chunks, ROUND(SUM(CASE WHEN file_system_part_chunk_status = 2 THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2) as progress_percentage, SUM(CASE WHEN file_system_part_chunk_status = 3 THEN 1 ELSE 0 END) as failed_chunks FROM file_system_part WHERE file_system_part_file_id IN
#{fileId}
GROUP BY file_system_part_file_id

SELECT DISTINCT file_system_part_chunk_path
FROM file_system_part
WHERE file_system_part_chunk_path IS NOT NULL
AND file_system_part_chunk_path != ''

    AND file_system_part_file_id = #{fileId}


    AND file_system_part_chunk_status = #{status}


    AND TIMESTAMPDIFF(HOUR, update_time, NOW()) > #{olderThanHours}

mapper.delete:
DELETE FROM file_system_part
WHERE file_system_part_chunk_status IN

    #{status}


    AND TIMESTAMPDIFF(HOUR, update_time, NOW()) > #{olderThanHours}
